import re
import subprocess
import shlex
from flask import Flask, request, jsonify

app = Flask(__name__)

# Limits to mitigate resource exhaustion (CWE-400)
MAX_REGEX_LENGTH = 500
MAX_FLAGS_LENGTH = 100
MAX_OUTPUT_BYTES = 5 * 1024 * 1024  # 5 MB cap on ps output
PS_TIMEOUT_SECONDS = 10

# Allowlist of characters permitted in ps flags to prevent command injection (CWE-78).
# ps flags are typically letters, digits, dashes, and spaces.
FLAGS_ALLOWED_RE = re.compile(r'^[A-Za-z0-9\-\s]*$')

# Allowlist of ps flags that are considered safe. We restrict to a known-safe set
# to avoid flags that could spawn commands or read arbitrary files.
SAFE_FLAG_TOKENS = {
    'a', 'u', 'x', 'e', 'f', 'l', 'j', 'r', 's', 't', 'T', 'w', 'w', 'W',
    'A', 'C', 'E', 'F', 'G', 'H', 'L', 'M', 'N', 'O', 'P', 'S', 'U', 'V', 'X',
    'Z', 'c', 'g', 'h', 'n', 'o', 'p', 'y', 'ww', 'aux', 'auxf', 'auxww',
    '-a', '-e', '-f', '-l', '-u', '-x', '-A', '-C', '-E', '-F', '-G', '-H',
    '-L', '-M', '-N', '-O', '-P', '-S', '-T', '-U', '-V', '-X', '-Z',
    '-o', '-p', '-t', '-w',
}


def _error(code, message, http_status):
    return jsonify({"code": code, "message": message}), http_status


def _validate_flags(filter_flags):
    """Validate the ps flags string. Returns (ok, tokens_or_error)."""
    if filter_flags is None:
        return True, []
    if not isinstance(filter_flags, str):
        return False, "filter_flags must be a string"
    if len(filter_flags) > MAX_FLAGS_LENGTH:
        return False, "filter_flags too long"
    if not FLAGS_ALLOWED_RE.match(filter_flags):
        return False, "filter_flags contains invalid characters"

    # Split into tokens; each token must be in the safe allowlist.
    tokens = filter_flags.split()
    for tok in tokens:
        if tok not in SAFE_FLAG_TOKENS:
            return False, "filter_flags contains unsupported flag"
    return True, tokens


def _run_ps(tokens):
    """Run ps with the given validated flag tokens. Returns (ok, stdout_or_error)."""
    # Build argv directly (no shell) to avoid shell injection (CWE-78).
    argv = ['ps'] + tokens
    try:
        proc = subprocess.run(
            argv,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=PS_TIMEOUT_SECONDS,
            check=False,
        )
    except FileNotFoundError:
        return False, "ps command not available on this server"
    except subprocess.TimeoutExpired:
        return False, "ps command timed out"
    except Exception:
        return False, "failed to execute ps command"

    if proc.returncode != 0:
        return False, "ps command failed"

    out = proc.stdout
    if len(out) > MAX_OUTPUT_BYTES:
        out = out[:MAX_OUTPUT_BYTES]
    return True, out


def _parse_ps_output(raw_bytes):
    """Parse ps output into (pid, full_line) tuples."""
    try:
        text = raw_bytes.decode('utf-8', errors='replace')
    except Exception:
        return []

    results = []
    lines = text.splitlines()
    if not lines:
        return results

    # First line is the header; find the PID column index.
    header = lines[0].split()
    try:
        pid_idx = header.index('PID')
    except ValueError:
        pid_idx = 0

    for line in lines[1:]:
        stripped = line.strip()
        if not stripped:
            continue
        fields = stripped.split(None, pid_idx + 1)
        if len(fields) <= pid_idx:
            continue
        try:
            pid = int(fields[pid_idx])
        except (ValueError, IndexError):
            continue
        results.append({"processId": pid, "processString": stripped})
    return results


@app.route('/monitor/commands', methods=['POST'])
def monitor_commands():
    try:
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            return _error(400, "Request body must be a JSON object", 400)

        command_regex = data.get('command_regex')
        if command_regex is None:
            return _error(400, "command_regex is required", 400)
        if not isinstance(command_regex, str):
            return _error(400, "command_regex must be a string", 400)
        if len(command_regex) > MAX_REGEX_LENGTH:
            return _error(400, "command_regex too long", 400)

        filter_flags = data.get('filter_flags')

        ok, tokens_or_err = _validate_flags(filter_flags)
        if not ok:
            return _error(400, tokens_or_err, 400)
        tokens = tokens_or_err

        # Compile the user regex safely. Python's re is not vulnerable to
        # catastrophic backtracking in the same way as PCRE, but we still
        # cap length and handle errors.
        try:
            pattern = re.compile(command_regex)
        except re.error:
            return _error(400, "Invalid regular expression", 400)

        ok, out_or_err = _run_ps(tokens)
        if not ok:
            return _error(500, out_or_err, 500)

        processes = _parse_ps_output(out_or_err)

        # Filter by regex against the full process string.
        matched = []
        for p in processes:
            try:
                if pattern.search(p["processString"]):
                    matched.append(p)
            except re.error:
                # Should not happen since pattern compiled, but be safe.
                continue

        return jsonify(matched), 200

    except Exception:
        # Catch-all to avoid leaking internals and to satisfy CWE-703.
        return _error(500, "Internal server error", 500)


@app.errorhandler(404)
def not_found(_e):
    return _error(404, "Not found", 404)


@app.errorhandler(405)
def method_not_allowed(_e):
    return _error(405, "Method not allowed", 405)


@app.errorhandler(500)
def internal_error(_e):
    return _error(500, "Internal server error", 500)


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
